style:
.tw-cosolar--cangyan.resume-paper {
  color: #2b3442;
}

.tw-cosolar--cangyan.resume-paper .paper-header {
  position: relative;
  margin: calc(var(--paper-mt, 15mm) * -1) calc(var(--paper-mr, 15mm) * -1) 7mm calc(var(--paper-ml, 15mm) * -1);
  padding: calc(9mm + var(--paper-mt, 15mm)) var(--paper-mr, 15mm) 13mm var(--paper-ml, 15mm);
  border: none;
  background: linear-gradient(122deg, #2b507d 0%, #1d3557 54%, #16283f 100%);
  color: #fff;
  overflow: hidden;
  clip-path: polygon(0 0, 100% 0, 100% 84%, 68% 100%, 0 100%);
  print-color-adjust: exact;
}

.tw-cosolar--cangyan.resume-paper .paper-header::before {
  content: "";
  position: absolute;
  top: -26mm;
  right: -10mm;
  width: 78mm;
  height: 78mm;
  background: rgba(255, 255, 255, 0.07);
  clip-path: polygon(50% 0, 100% 50%, 50% 100%, 0 50%);
  print-color-adjust: exact;
}

.tw-cosolar--cangyan.resume-paper .paper-header::after {
  content: "";
  position: absolute;
  right: -4mm;
  bottom: 4mm;
  width: 52mm;
  height: 2.4mm;
  background: #5b8cc4;
  transform: rotate(-11deg);
  print-color-adjust: exact;
}

.tw-cosolar--cangyan.resume-paper .paper-header > * {
  position: relative;
  z-index: 1;
}

.tw-cosolar--cangyan.resume-paper .paper-header--photo {
  align-items: center;
  gap: 8mm;
}

.tw-cosolar--cangyan.resume-paper .paper-photo {
  width: 28mm;
  height: 28mm;
  border: 0.8mm solid #fff;
  border-radius: 50%;
  box-shadow: 0 0 0 1.2mm rgba(255, 255, 255, 0.24), 0 2mm 6mm -2mm rgba(0, 0, 0, 0.5);
  print-color-adjust: exact;
}

.tw-cosolar--cangyan.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 1.8);
  font-weight: 600;
}

.tw-cosolar--cangyan.resume-paper .paper-name {
  color: #fff;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.15);
  letter-spacing: 0.1em;
}

.tw-cosolar--cangyan.resume-paper .paper-identity {
  padding: 0.3mm 2mm;
  border-color: rgba(255, 255, 255, 0.36);
  background: rgba(255, 255, 255, 0.12);
  color: #fff;
}

.tw-cosolar--cangyan.resume-paper .paper-role {
  color: rgba(255, 255, 255, 0.94);
  font-weight: 600;
}

.tw-cosolar--cangyan.resume-paper .paper-role::before {
  content: "求职意向：";
  color: rgba(255, 255, 255, 0.66);
  font-weight: 400;
  font-size: calc(var(--paper-base-size) * 0.92);
}

.tw-cosolar--cangyan.resume-paper .paper-contacts--labeled {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.3mm 7mm;
  max-width: 126mm;
  margin-top: 4mm;
  padding-top: 3.4mm;
  border-top: 1px solid rgba(255, 255, 255, 0.2);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 0.87);
}

.tw-cosolar--cangyan.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-cosolar--cangyan.resume-paper .paper-contact__label {
  color: rgba(255, 255, 255, 0.62);
  font-weight: 600;
}

.tw-cosolar--cangyan.resume-paper .paper-style-icon .paper-section__title {
  color: #1d3557;
  letter-spacing: 0.06em;
}

.tw-cosolar--cangyan.resume-paper .paper-style-icon .paper-section__icon {
  width: 6.2mm;
  height: 6.8mm;
  border: none;
  border-radius: 0;
  background: var(--paper-accent);
  color: #fff;
  clip-path: polygon(25% 0, 75% 0, 100% 50%, 75% 100%, 25% 100%, 0 50%);
  print-color-adjust: exact;
}

.tw-cosolar--cangyan.resume-paper .paper-style-icon .paper-section__title::before {
  order: 1;
  margin-left: 1.8mm;
  color: #6f86a4;
  font-size: calc(var(--paper-base-size) * 0.78);
  font-weight: 400;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.tw-cosolar--cangyan.resume-paper .paper-style-icon .paper-section__title::after {
  order: 2;
  border-top: 1px solid #dde5ef;
}

.tw-cosolar--cangyan.resume-paper .is-job_intention .paper-section__title::before { content: "Intention"; }
.tw-cosolar--cangyan.resume-paper .is-education .paper-section__title::before { content: "Education"; }
.tw-cosolar--cangyan.resume-paper .is-work_experience .paper-section__title::before { content: "Experience"; }
.tw-cosolar--cangyan.resume-paper .is-project_experience .paper-section__title::before { content: "Projects"; }
.tw-cosolar--cangyan.resume-paper .is-campus_experience .paper-section__title::before { content: "Internship"; }
.tw-cosolar--cangyan.resume-paper .is-skills_summary .paper-section__title::before { content: "Skills"; }
.tw-cosolar--cangyan.resume-paper .is-skill_proficiency .paper-section__title::before { content: "Proficiency"; }
.tw-cosolar--cangyan.resume-paper .is-self_evaluation .paper-section__title::before { content: "About Me"; }
.tw-cosolar--cangyan.resume-paper .is-paper_publication .paper-section__title::before { content: "Papers"; }
.tw-cosolar--cangyan.resume-paper .is-journal_paper .paper-section__title::before { content: "Journals"; }
.tw-cosolar--cangyan.resume-paper .is-portfolio .paper-section__title::before { content: "Portfolio"; }
.tw-cosolar--cangyan.resume-paper .is-postgraduate_info .paper-section__title::before { content: "Postgraduate"; }
.tw-cosolar--cangyan.resume-paper .is-competition .paper-section__title::before { content: "Contest"; }
.tw-cosolar--cangyan.resume-paper .is-award .paper-section__title::before { content: "Awards"; }
.tw-cosolar--cangyan.resume-paper .is-certificate .paper-section__title::before { content: "Certificates"; }
.tw-cosolar--cangyan.resume-paper .is-hobby .paper-section__title::before { content: "Interests"; }

.tw-cosolar--cangyan.resume-paper .is-education .paper-item,
.tw-cosolar--cangyan.resume-paper .is-work_experience .paper-item,
.tw-cosolar--cangyan.resume-paper .is-project_experience .paper-item {
  position: relative;
}

.tw-cosolar--cangyan.resume-paper .is-education .paper-item-head,
.tw-cosolar--cangyan.resume-paper .is-work_experience .paper-item-head,
.tw-cosolar--cangyan.resume-paper .is-project_experience .paper-item-head {
  display: grid;
  grid-template-columns: 30mm minmax(0, 1fr);
  column-gap: 3.5mm;
  padding-right: 30%;
  align-items: baseline;
}

.tw-cosolar--cangyan.resume-paper .is-education .paper-item-period,
.tw-cosolar--cangyan.resume-paper .is-work_experience .paper-item-period,
.tw-cosolar--cangyan.resume-paper .is-project_experience .paper-item-period {
  order: -1;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 0.86);
  font-weight: 700;
  white-space: nowrap;
}

.tw-cosolar--cangyan.resume-paper .is-education .paper-item-sub,
.tw-cosolar--cangyan.resume-paper .is-work_experience .paper-item-sub,
.tw-cosolar--cangyan.resume-paper .is-project_experience .paper-item-sub {
  position: absolute;
  top: 0;
  right: 0;
  justify-content: flex-end;
  max-width: 30%;
  margin-top: 0;
  color: #5c6b7d;
  font-size: calc(var(--paper-base-size) * 0.9);
  text-align: right;
}

.tw-cosolar--cangyan.resume-paper .paper-item-title {
  color: #1d3557;
}

.tw-cosolar--cangyan.resume-paper .paper-item-sub a {
  color: var(--paper-accent);
}

.tw-cosolar--cangyan.resume-paper .paper-item-tag {
  color: #2f5c8f;
  border-color: #dbe4f0;
}

.tw-cosolar--cangyan.resume-paper .paper-note__tag {
  padding: 0;
  border: none;
  border-radius: 0;
  color: #2f5c8f;
  font-weight: 600;
}

.tw-cosolar--cangyan.resume-paper .paper-note__tag::after {
  content: "：";
}

.tw-cosolar--cangyan.resume-paper .paper-footer {
  border-top: 1px solid #dde5ef;
  color: #74849a;
}
